  color: #2a1b0d;
}
.brand-title i { font-style: italic; color: var(--rust); }
.brand-sub { font-size: 6.5px; letter-spacing: .27em; color: #8c6c45; margin-left: 1px; }
.topbar-actions { display: flex; align-items: center; gap: 7px; }
.topbar .sound-btn { width: 34px; height: 34px; background: rgba(255,255,255,.25); }

.home-main {
  flex: 1;
  min-height: 0;
  padding: 3px 14px 0;
  display: flex;
  flex-direction: column;
  gap: 9px;
  position: relative;
  z-index: 2;
}
.season-line {
  height: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 3px;
  font-size: 7.5px;
  color: #8a6a42;
  letter-spacing: .18em;
}
.season-rule { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(103,73,37,.2), transparent); }
.weather { display: flex; align-items: center; gap: 5px; color: #8b6236; letter-spacing: .12em; }
.weather-sun { width: 8px; height: 8px; border-radius: 50%; background: #d59b40; box-shadow: 0 0 0 3px rgba(213,155,64,.17); }

.hero {
  position: relative;
  flex: 0 0 auto;
  height: clamp(294px, 41.5vh, 354px);
  min-height: 272px;
  border-radius: 25px;
  overflow: hidden;
  background: #d6a25d;
  box-shadow: 0 18px 38px rgba(85, 50, 15, .22), 0 2px 0 rgba(255,255,255,.4) inset;
  isolation: isolate;
  border: 1px solid rgba(89, 53, 17, .16);
}
.hero-art, .hero-art svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.hero-art svg { object-fit: cover; }
.hero-vignette {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(29,17,6,.18) 0%, transparent 28%, transparent 48%, rgba(31,17,5,.28) 66%, rgba(24,13,5,.85) 100%),
    radial-gradient(ellipse at 50% 38%, transparent 42%, rgba(44,24,7,.16) 100%);
}
