import { drawArtifact, drawArtifactShadow } from './art.js';
import { levelFor, cleaningGrade } from './data.js';

const clamp = (n, a, b) => Math.max(a, Math.min(b, n));

function seeded(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export class CleanScene {
  constructor({ canvas, stage, state, artifact, audio, onUpdate, onPhase, onComplete, onHint }) {
    this.canvas = canvas;
    this.stage = stage;
    this.ctx = canvas.getContext('2d');
    this.state = state;
    this.artifact = artifact;
    this.audio = audio;
    this.onUpdate = onUpdate || (() => {});
    this.onPhase = onPhase || (() => {});
    this.onComplete = onComplete || (() => {});
    this.onHint = onHint || (() => {});

    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.w = 0;
    this.h = 0;
    this.tool = 'brush';
    this.phase = 'clean';
    this.drawing = false;
    this.pointer = null;
    this.last = null;
    this.particles = [];
    this.raf = 0;
    this.started = false;
    this.completed = false;
    this.polish = 0;
    this.dirtCount = 0;
    this.saltCount = 0;
    this.dirtTotal = 1;
    this.saltTotal = 1;
    this.lastHaptic = 0;
    this.lastSound = 0;
    this.lastHint = 0;

    this.onDown = this.onDown.bind(this);
    this.onMove = this.onMove.bind(this);
    this.onUp = this.onUp.bind(this);
    this.loop = this.loop.bind(this);

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(stage);
    this.bind();
    this.resize();
    this.raf = requestAnimationFrame(this.loop);
  }

  bind() {
    this.canvas.addEventListener('pointerdown', this.onDown, { passive: false });
    this.canvas.addEventListener('pointermove', this.onMove, { passive: false });
    this.canvas.addEventListener('pointerup', this.onUp);
    this.canvas.addEventListener('pointercancel', this.onUp);
    this.canvas.addEventListener('pointerleave', () => {
      if (!this.drawing) this.pointer = null;
    });
  }

  destroy() {
    this.resizeObserver.disconnect();
    cancelAnimationFrame(this.raf);
    this.canvas.removeEventListener('pointerdown', this.onDown);
    this.canvas.removeEventListener('pointermove', this.onMove);
    this.canvas.removeEventListener('pointerup', this.onUp);
    this.canvas.removeEventListener('pointercancel', this.onUp);
  }

  resize() {
    const rect = this.stage.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const w = Math.round(rect.width);
    const h = Math.round(rect.height);
    if (w === this.w && h === this.h) return;
    this.w = w;
    this.h = h;
    this.canvas.width = Math.round(w * this.dpr);
    this.canvas.height = Math.round(h * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.build();
    this.started = true;
    this.emit();
  }

  makeCanvas() {
    const c = document.createElement('canvas');
    c.width = Math.round(this.w * this.dpr);
    c.height = Math.round(this.h * this.dpr);
    const ctx = c.getContext('2d');
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    return { c, ctx };
  }

  build() {
    const { w, h } = this;
    this.bg = this.makeCanvas();
    this.base = this.makeCanvas();
    this.dirt = this.makeCanvas();
    this.salt = this.makeCanvas();
    this.mask = this.makeCanvas();

    this.cx = w * .5;
    this.cy = h * .52;
    this.size = Math.min(w, h) * .64;

    this.paintBackground();
    drawArtifact(this.base.ctx, this.artifact.art, this.cx, this.cy, this.size);

    this.mask.ctx.clearRect(0, 0, w, h);
    drawArtifact(this.mask.ctx, this.artifact.art, this.cx, this.cy, this.size);

    this.paintDirt();
    this.paintSalt();
    this.buildGrid();

    this.particles.length = 0;
    this.pointer = null;
    this.last = null;
    this.drawing = false;
    this.completed = false;
    this.polish = 0;
    this.phase = 'clean';
    this.dirtCount = this.dirtTotal;
    this.saltCount = this.saltTotal;
  }

  paintBackground() {
    const { ctx } = this.bg;
    const { w, h } = this;
    const g = ctx.createRadialGradient(w * .5, h * .42, 10, w * .5, h * .48, Math.max(w, h) * .72);
    g.addColorStop(0, '#32413b');
    g.addColorStop(.48, '#1b2723');
    g.addColorStop(1, '#0c1311');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // faint conservation grid
    ctx.strokeStyle = 'rgba(186, 220, 204, .045)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x += 28) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
    }
    for (let y = 0; y <= h; y += 28) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }

    // tray rim
    const inset = Math.min(w, h) * .08;
    const r = 16;
    ctx.beginPath();
    ctx.roundRect(inset, inset, w - inset * 2, h - inset * 2, r);
    ctx.fillStyle = 'rgba(255,255,255,.018)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(198, 226, 211, .12)';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.beginPath();
    ctx.roundRect(inset + 4, inset + 4, w - inset * 2 - 8, h - inset * 2 - 8, r - 4);
    ctx.strokeStyle = 'rgba(198, 226, 211, .045)';
    ctx.stroke();

    // ruler ticks
    ctx.strokeStyle = 'rgba(198, 226, 211, .12)';
    for (let i = 0; i < 17; i++) {
      const x = inset + 12 + i * ((w - inset * 2 - 24) / 16);
      const len = i % 4 === 0 ? 7 : 3;
      ctx.beginPath();
      ctx.moveTo(x, h - inset - 9);
      ctx.lineTo(x, h - inset - 9 - len);
      ctx.stroke();
    }

    // ambient dust
    const rr = seeded(91);
    for (let i = 0; i < 55; i++) {
      ctx.beginPath();
      ctx.arc(rr() * w, rr() * h, .3 + rr() * 1.1, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(220, 236, 224, ${.03 + rr() * .08})`;
      ctx.fill();
    }

    drawArtifactShadow(ctx, this.cx, this.cy, this.size, .5);

    // glass reflection
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const sheen = ctx.createLinearGradient(0, inset, w, h * .7);
    sheen.addColorStop(0, 'rgba(255,255,255,.025)');
    sheen.addColorStop(.35, 'rgba(255,255,255,0)');
    sheen.addColorStop(.62, 'rgba(255,255,255,.018)');
    sheen.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = sheen;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  }

  paintDirt() {
    const { ctx } = this.dirt;
    const { w, h } = this;
    ctx.clearRect(0, 0, w, h);
    const rr = seeded(113);

    ctx.fillStyle = 'rgba(72, 54, 35, .92)';
    ctx.fillRect(0, 0, w, h);

    // mottled encrustation
    for (let i = 0; i < 130; i++) {
      const x = rr() * w, y = rr() * h;
      const rw = 3 + rr() * 20, rh = 2 + rr() * 13;
      const g = ctx.createRadialGradient(x, y, 0, x, y, rw);
      const dark = rr() > .46;
      g.addColorStop(0, dark ? `rgba(45, 32, 20, ${.16 + rr() * .28})` : `rgba(137, 108, 72, ${.1 + rr() * .23})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(1, rh / rw);
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(0, 0, rw, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // grime grain
    for (let i = 0; i < 460; i++) {
      ctx.beginPath();
      ctx.arc(rr() * w, rr() * h, .3 + rr() * 1.6, 0, Math.PI * 2);
      ctx.fillStyle = rr() > .5 ? `rgba(154, 123, 79, ${.05 + rr() * .17})` : `rgba(38, 27, 17, ${.06 + rr() * .18})`;
      ctx.fill();
    }

    // crust cracks
    ctx.strokeStyle = 'rgba(35, 24, 15, .32)';
    for (let i = 0; i < 12; i++) {
      let x = rr() * w, y = rr() * h;
      ctx.beginPath();
      ctx.moveTo(x, y);
      for (let j = 0; j < 4; j++) {
        x += (rr() - .5) * 28;
        y += (rr() - .5) * 28;
        ctx.lineTo(x, y);
      }
      ctx.lineWidth = .6 + rr() * .8;
      ctx.stroke();
    }

    // clip to artifact silhouette
    ctx.save();
    ctx.globalCompositeOperation = 'destination-in';
    ctx.drawImage(this.mask.c, 0, 0, w, h);
    ctx.restore();
  }

  paintSalt() {
    const { ctx } = this.salt;
    const { w, h } = this;
    ctx.clearRect(0, 0, w, h);
    const rr = seeded(451);

    // base crust
    ctx.fillStyle = 'rgba(226, 224, 207, .8)';
    ctx.fillRect(0, 0, w, h);

    // crystalline blooms
    for (let i = 0; i < 80; i++) {
      const x = rr() * w, y = rr() * h;
      const r = 4 + rr() * 18;
      const g = ctx.createRadialGradient(x - r * .2, y - r * .25, 0, x, y, r);
      g.addColorStop(0, `rgba(255, 253, 239, ${.3 + rr() * .3})`);
      g.addColorStop(.55, `rgba(211, 219, 207, ${.13 + rr() * .2})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }

    // salt veins / crack fill
    for (let i = 0; i < 22; i++) {
      let x = rr() * w, y = rr() * h;
      ctx.beginPath();
      ctx.moveTo(x, y);
      for (let j = 0; j < 4; j++) {
        x += (rr() - .5) * 18;
        y += (rr() - .5) * 18;
        ctx.lineTo(x, y);
      }
      ctx.strokeStyle = `rgba(248, 247, 231, ${.08 + rr() * .22})`;
      ctx.lineWidth = 1 + rr() * 2.6;
      ctx.stroke();
    }

    // blue-grey shadows in the salt
    for (let i = 0; i < 30; i++) {
      ctx.beginPath();
      ctx.arc(rr() * w, rr() * h, 2 + rr() * 9, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(117, 139, 133, ${.025 + rr() * .09})`;
      ctx.fill();
    }

    // clip
    ctx.save();
    ctx.globalCompositeOperation = 'destination-in';
    ctx.drawImage(this.mask.c, 0, 0, w, h);
    ctx.restore();
  }

  buildGrid() {
    const { w, h } = this;
    const mw = this.mask.c.width;
    const mh = this.mask.c.height;
    const data = this.mask.ctx.getImageData(0, 0, mw, mh).data;
    this.cell = Math.max(4, Math.round(Math.min(w, h) / 58));
    this.cols = Math.ceil(w / this.cell);
    this.rows = Math.ceil(h / this.cell);
    this.gridMask = new Uint8Array(this.cols * this.rows);
    this.dirtGrid = new Uint8Array(this.cols * this.rows);
    this.saltGrid = new Uint8Array(this.cols * this.rows);
    this.dirtTotal = 0;
    this.saltTotal = 0;
    for (let gy = 0; gy < this.rows; gy++) {
      for (let gx = 0; gx < this.cols; gx++) {
        const x = Math.round((gx + .5) * this.cell * this.dpr);
        const y = Math.round((gy + .5) * this.cell * this.dpr);
        if (x < 0 || y < 0 || x >= mw || y >= mh) continue;
        if (data[(y * mw + x) * 4 + 3] > 32) {
          const idx = gy * this.cols + gx;
          this.gridMask[idx] = 1;
          this.dirtGrid[idx] = 1;
          this.saltGrid[idx] = 1;
          this.dirtTotal++;
          this.saltTotal++;
        }
      }
    }
    this.dirtCount = this.dirtTotal;
    this.saltCount = this.saltTotal;
  }

  setTool(tool) {
    if (tool === this.tool) return;
    this.tool = tool;
    this.pointer = null;
    this.audio.click();
  }

  point(e) {
    const rect = this.canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  }

  onDown(e) {
    if (this.completed) return;
    e.preventDefault();
    this.audio.ensure();
    this.drawing = true;
    this.canvas.setPointerCapture?.(e.pointerId);
    const p = this.point(e);
    this.last = p;
    this.pointer = p;
    this.applyTool(p.x, p.y);
    this.stage.dispatchEvent(new CustomEvent('clean-start'));
  }

  onMove(e) {
    if (this.completed) return;
    const p = this.point(e);
    this.pointer = p;
    if (!this.drawing) return;
    e.preventDefault();
    if (this.last) {
      const dx = p.x - this.last.x, dy = p.y - this.last.y;
      const dist = Math.hypot(dx, dy);
      const steps = Math.max(1, Math.ceil(dist / 6));
      for (let i = 1; i <= steps; i++) {
        this.applyTool(this.last.x + dx * (i / steps), this.last.y + dy * (i / steps));
      }
    } else {
      this.applyTool(p.x, p.y);
    }
    this.last = p;
  }

  onUp() {
    this.drawing = false;
    this.last = null;
    this.emit();
  }

  toolRadius() {
    const scale = Math.min(1.2, Math.max(.8, Math.min(this.w, this.h) / 360));
    if (this.tool === 'brush') return (46 + (levelFor(this.state, 'brush') - 1) * 6) * scale;
    if (this.tool === 'water') return (58 + (levelFor(this.state, 'water') - 1) * 8) * scale;
    return (44 + (levelFor(this.state, 'cloth') - 1) * 6) * scale;
  }

  applyTool(x, y) {
    if (this.phase === 'done') return;
    const radius = this.toolRadius();
    if (this.tool === 'brush') {
      if (this.phase === 'polish') {
        this.hint('The crust is gone — buff it with the cloth.', 900);
        return;
      }
      const before = this.dirtCount;
      this.erase(this.dirt.ctx, x, y, radius);
      this.mark('dirt', x, y, radius * .88);
      if (this.dirtCount < before) {
        this.audio.brush();
        this.spawnDust(x, y, radius, 'rgba(105, 82, 54,');
        this.haptic(5);
      }
      if (this.dirtCount / this.dirtTotal > .28 && this.saltCount / this.saltTotal < .3) {
        this.hint('Salt crust remains. Switch to the water tool.', 1500);
      }
    } else if (this.tool === 'water') {
      if (this.phase === 'polish') {
        this.hint('The crust is gone — buff it with the cloth.', 900);
        return;
      }
      const before = this.saltCount;
      this.erase(this.salt.ctx, x, y, radius);
      this.mark('salt', x, y, radius * .92);
      if (this.saltCount < before) {
        this.audio.water();
        this.spawnWater(x, y, radius);
        this.haptic(4);
      }
      if (this.saltCount / this.saltTotal > .28 && this.dirtCount / this.dirtTotal < .3) {
        this.hint('The grime needs a dry brush first.', 1500);
      }
    } else {
      if (this.phase === 'clean') {
        this.hint('Clear the grime and salt before polishing.', 1300);
        return;
      }
      const level = levelFor(this.state, 'cloth');
      this.polish = clamp(this.polish + .009 * (1 + (level - 1) * .26), 0, 1);
      this.audio.cloth();
      this.spawnSpark(x, y, radius);
      this.haptic(3);
      if (this.polish >= 1 && !this.completed) this.finish();
    }
    this.checkPhase();
    this.emit();
  }

  erase(ctx, x, y, radius) {
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    const g = ctx.createRadialGradient(x, y, radius * .22, x, y, radius);
    g.addColorStop(0, 'rgba(0,0,0,1)');
    g.addColorStop(.72, 'rgba(0,0,0,.93)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  mark(kind, x, y, radius) {
    const grid = kind === 'dirt' ? this.dirtGrid : this.saltGrid;
    const cs = this.cell;
    const x0 = Math.max(0, Math.floor((x - radius) / cs));
    const x1 = Math.min(this.cols - 1, Math.ceil((x + radius) / cs));
    const y0 = Math.max(0, Math.floor((y - radius) / cs));
    const y1 = Math.min(this.rows - 1, Math.ceil((y + radius) / cs));
    let removed = 0;
    for (let gy = y0; gy <= y1; gy++) {
      for (let gx = x0; gx <= x1; gx++) {
        const idx = gy * this.cols + gx;
        if (!this.gridMask[idx] || !grid[idx]) continue;
        const cx = (gx + .5) * cs;
        const cy = (gy + .5) * cs;
        if (Math.hypot(cx - x, cy - y) <= radius) {
          grid[idx] = 0;
          removed++;
        }
      }
    }
    if (kind === 'dirt') this.dirtCount = Math.max(0, this.dirtCount - removed);
    else this.saltCount = Math.max(0, this.saltCount - removed);
  }

  checkPhase() {
    if (this.phase === 'clean') {
      const dirt = this.dirtCount / Math.max(1, this.dirtTotal);
      const salt = this.saltCount / Math.max(1, this.saltTotal);
      if (dirt <= .14 && salt <= .14) {
        this.phase = 'polish';
        this.polish = 0;
        this.audio.discover();
        if (navigator.vibrate) navigator.vibrate([18, 35, 18]);
        this.onPhase('polish');
      }
    }
  }

  finish() {
    this.completed = true;
    this.phase = 'done';
    this.audio.complete();
    if (navigator.vibrate) navigator.vibrate([25, 50, 30, 50, 80]);
    const dirt = this.dirtCount / Math.max(1, this.dirtTotal);
    const salt = this.saltCount / Math.max(1, this.saltTotal);
    const lab = cleaningGrade(this.state);
    const penalty = Math.max(0, this.artifact.fragility - lab) * 6;
    const condition = Math.round(clamp(100 - dirt * 22 - salt * 22 - penalty, 52, 100));
    this.onPhase('done');
    this.onComplete({ condition, dirt, salt, polish: this.polish, lab });
    this.emit();
  }

  emit() {
    const dirt = this.dirtCount / Math.max(1, this.dirtTotal);
    const salt = this.saltCount / Math.max(1, this.saltTotal);
    this.onUpdate({
      dirt,
      salt,
      polish: this.polish,
      phase: this.phase,
      tool: this.tool
    });
  }

  hint(message, cooldown = 1000) {
    const now = performance.now();
    if (now - this.lastHint < cooldown) return;
    this.lastHint = now;
    this.onHint(message);
  }

  haptic(ms) {
    const now = performance.now();
    if (now - this.lastHaptic < 110) return;
    this.lastHaptic = now;
    if (navigator.vibrate) navigator.vibrate(ms);
  }

  spawnDust(x, y, radius, color) {
    for (let i = 0; i < 4; i++) {
      const a = Math.random() * Math.PI * 2;
      this.particles.push({
        type: 'dust',
        x: x + Math.cos(a) * radius * .7,
        y: y + Math.sin(a) * radius * .7,
        vx: Math.cos(a) * (.4 + Math.random()),
        vy: Math.sin(a) * (.4 + Math.random()) - .4,
        r: .8 + Math.random() * 2.2,
        life: 1,
        decay: .02 + Math.random() * .025,
        color
      });
    }
    if (this.particles.length > 180) this.particles.splice(0, this.particles.length - 180);
  }

  spawnWater(x, y, radius) {
    for (let i = 0; i < 6; i++) {
      const a = Math.random() * Math.PI * 2;
      this.particles.push({
        type: 'water',
        x: x + Math.cos(a) * radius * .6,
        y: y + Math.sin(a) * radius * .6,
        vx: Math.cos(a) * (.5 + Math.random() * 1.4),
        vy: Math.sin(a) * (.5 + Math.random()) - .5,
        r: .8 + Math.random() * 2,
        life: 1,
        decay: .025 + Math.random() * .03,
        color: 'rgba(174, 226, 216,'
      });
    }
    if (this.particles.length > 180) this.particles.splice(0, this.particles.length - 180);
  }

  spawnSpark(x, y, radius) {
    if (Math.random() > .55) return;
    const a = Math.random() * Math.PI * 2;
    this.particles.push({
      type: 'spark',
      x: x + Math.cos(a) * radius * .8,
      y: y + Math.sin(a) * radius * .8,
      vx: Math.cos(a) * .25,
      vy: -.4 - Math.random() * .6,
      r: .8 + Math.random() * 1.8,
      life: 1,
      decay: .014 + Math.random() * .018,
      color: 'rgba(255, 236, 177,'
    });
  }

  loop() {
    if (!this.started) {
      this.raf = requestAnimationFrame(this.loop);
      return;
    }
    const ctx = this.ctx;
    const { w, h } = this;
    ctx.clearRect(0, 0, w, h);
    ctx.drawImage(this.bg.c, 0, 0, w, h);

    // reveal halo grows as the artifact gets cleaner
    const cleanAmount = 1 - (this.dirtCount / Math.max(1, this.dirtTotal) + this.saltCount / Math.max(1, this.saltTotal)) / 2;
    if (cleanAmount > .2) {
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      const glow = ctx.createRadialGradient(this.cx, this.cy, this.size * .1, this.cx, this.cy, this.size * .6);
      glow.addColorStop(0, `rgba(255, 232, 174, ${.06 * cleanAmount})`);
      glow.addColorStop(1, 'rgba(255,232,174,0)');
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, w, h);
      ctx.restore();
    }

    ctx.drawImage(this.base.c, 0, 0, w, h);
    ctx.drawImage(this.dirt.c, 0, 0, w, h);
    ctx.drawImage(this.salt.c, 0, 0, w, h);

    // final lustre
    if (this.polish > 0) {
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.globalAlpha = this.polish * .36;
      const sh = ctx.createLinearGradient(this.cx - this.size * .4, this.cy - this.size * .4, this.cx + this.size * .4, this.cy + this.size * .4);
      sh.addColorStop(0, 'rgba(255, 250, 218, 0)');
      sh.addColorStop(.38, 'rgba(255, 245, 202, .55)');
      sh.addColorStop(.52, 'rgba(255, 255, 240, .1)');
      sh.addColorStop(.72, 'rgba(255, 240, 186, .32)');
      sh.addColorStop(1, 'rgba(255,250,218,0)');
      ctx.fillStyle = sh;
      ctx.beginPath();
      ctx.ellipse(this.cx, this.cy, this.size * .31, this.size * .35, -.3, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // twinkles
      const time = performance.now() * .001;
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (let i = 0; i < 4; i++) {
        const a = time * .45 + i * Math.PI / 2;
        const rad = this.size * (.3 + i * .018);
        const x = this.cx + Math.cos(a) * rad;
        const y = this.cy + Math.sin(a) * rad * .7;
        const tw = (Math.sin(time * 2.2 + i * 1.7) + 1) * .5;
        ctx.globalAlpha = this.polish * (.25 + tw * .55);
        ctx.strokeStyle = '#fff2c4';
        ctx.lineWidth = .8;
        ctx.beginPath();
        ctx.moveTo(x - 4, y); ctx.lineTo(x + 4, y);
        ctx.moveTo(x, y - 4); ctx.lineTo(x, y + 4);
        ctx.stroke();
      }
      ctx.restore();
    }

    // particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += p.type === 'water' ? .09 : p.type === 'spark' ? -.008 : .018;
      p.life -= p.decay;
      if (p.life <= 0) { this.particles.splice(i, 1); continue; }
      ctx.beginPath();
      if (p.type === 'spark') {
        ctx.fillStyle = p.color + (p.life * .9).toFixed(2) + ')';
        ctx.arc(p.x, p.y, p.r * p.life, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.fillStyle = p.color + (p.life * .6).toFixed(2) + ')';
        ctx.arc(p.x, p.y, p.r * p.life, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // cursor
    if (this.pointer && this.drawing) {
      const radius = this.toolRadius();
      ctx.save();
      ctx.beginPath();
      ctx.arc(this.pointer.x, this.pointer.y, radius, 0, Math.PI * 2);
      ctx.strokeStyle = this.tool === 'water' ? 'rgba(158, 220, 211, .55)' : this.tool === 'cloth' ? 'rgba(247, 220, 161, .55)' : 'rgba(255, 240, 211, .5)';
      ctx.lineWidth = 1.1;
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(this.pointer.x, this.pointer.y, 2.2, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,.35)';
      ctx.fill();
      ctx.restore();
    }

    // stage vignette
    const vig = ctx.createRadialGradient(w * .5, h * .5, Math.min(w, h) * .24, w * .5, h * .5, Math.max(w, h) * .75);
    vig.addColorStop(0, 'rgba(2,8,7,0)');
    vig.addColorStop(1, 'rgba(2,8,7,.36)');
    ctx.fillStyle = vig;
    ctx.fillRect(0, 0, w, h);

    this.raf = requestAnimationFrame(this.loop);
  }
}

import {
  STARTING_STATE, SITES, ARTIFACTS, UPGRADES, TOTAL_RELICS,
  rankFor, artifactFor, levelFor, upgradeCost, cleaningGrade
} from './data.js';
import { sceneSVG, drawArtifact, iconSvg } from './art.js';
import { AudioEngine } from './audio.js';
import { DigScene } from './dig.js';
import { CleanScene } from './clean.js';

const STORE_KEY = 'dune_and_dust_save_v3';
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));

const audio = new AudioEngine();
let digScene = null;
let cleanScene = null;
let shopTab = 'field';
let lastScreen = 'home';
let modalActions = [];
const imageCache = new Map();

/* ---------------------------------------------------------
   State
   --------------------------------------------------------- */
function freshState() {
  return JSON.parse(JSON.stringify(STARTING_STATE));
}

function loadState() {
  try {
    const raw = JSON.parse(localStorage.getItem(STORE_KEY));
    if (!raw || typeof raw !== 'object') return freshState();
    return {
      ...freshState(),
      ...raw,
      levels: { ...STARTING_STATE.levels, ...(raw.levels || {}) },
      flags: { ...STARTING_STATE.flags, ...(raw.flags || {}) },
      collection: Array.isArray(raw.collection) ? raw.collection : [],
      currentRelic: raw.currentRelic && typeof raw.currentRelic === 'object' ? raw.currentRelic : null,
      selectedSite: Number.isFinite(raw.selectedSite) ? clamp(raw.selectedSite, 0, SITES.length - 1) : 0
    };
  } catch {
    return freshState();
  }
}

const state = loadState();

function save() {
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify(state));
  } catch {
    // A full gallery should never break the expedition.
  }
}

function artifactImage(id, size = 340) {
  const key = `${id}_${size}`;
  if (imageCache.has(key)) return imageCache.get(key);
  const c = document.createElement('canvas');
  c.width = size;
  c.height = size;
  const ctx = c.getContext('2d');
  drawArtifact(ctx, artifactFor(id).art, size / 2, size / 2, size * .88);
  const url = c.toDataURL('image/webp', .92);
  imageCache.set(key, url);
  return url;
}

/* ---------------------------------------------------------
   Utilities
   --------------------------------------------------------- */
function money(n) {
  return '$' + Math.round(n).toLocaleString('en-US');
}

function formatName(name) {
  const words = name.split(' ');
  if (words.length <= 2) return name;
  if (name.startsWith('The ')) {
    return `${words.slice(0, 2).join(' ')}<br>${words.slice(2).join(' ')}`;
  }
  const mid = Math.ceil(words.length / 2);
  return `${words.slice(0, mid).join(' ')}<br>${words.slice(mid).join(' ')}`;
}

function siteIndexLabel(site) {
  return `Site ${String(site.index).padStart(2, '0')} · ${site.region.split(' · ')[0]}`;
}

function gradeText(condition) {
  if (condition >= 96) return 'Museum';
  if (condition >= 89) return 'Excellent';
  if (condition >= 80) return 'Fine';
  if (condition >= 70) return 'Stable';
  return 'Study';
}

function gradeLetter(condition) {
  if (condition >= 96) return 'A+';
  if (condition >= 90) return 'A';
  if (condition >= 84) return 'B+';
  if (condition >= 76) return 'B';
  if (condition >= 68) return 'C';
  return 'D';
}

function vibrate(pattern) {
  if (navigator.vibrate) navigator.vibrate(pattern);
}

function updateSoundButtons() {
  $$('.sound-btn').forEach(btn => {
    const use = btn.querySelector('use');
    if (use) use.setAttribute('href', audio.muted ? '#i-mute' : '#i-sound');
    btn.setAttribute('aria-label', audio.muted ? 'Unmute sound' : 'Mute sound');
  });
}

function updateWallet(bump = false) {
  $$('.coin-value').forEach(el => { el.textContent = Math.round(state.coins).toLocaleString('en-US'); });
  if (bump) {
    $$('.wallet').forEach(el => {
      el.classList.remove('is-bumping');
      void el.offsetWidth;
      el.classList.add('is-bumping');
    });
  }
}

let toastTimer = 0;
function toast(message, duration = 2500) {
  const layer = $('#toastLayer');
  const el = document.createElement('div');
  el.className = 'toast';
  el.textContent = message;
  layer.appendChild(el);
  clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => {
    el.classList.add('is-leaving');
    setTimeout(() => el.remove(), 320);
  }, duration);
}

/* ---------------------------------------------------------
   Modal
   --------------------------------------------------------- */
function openModal({ kicker = 'A note from the field', title, text = '', bodyHTML = '', actions = [] }) {
  $('#modalKicker').textContent = kicker;
  $('#modalTitle').textContent = title;
  const textEl = $('#modalText');
  if (bodyHTML) textEl.innerHTML = bodyHTML;
  else {
    textEl.textContent = text;
    textEl.hidden = !text;
  }
  if (bodyHTML) textEl.hidden = false;
  const wrap = $('#modalActions');
  wrap.innerHTML = '';
  modalActions = actions;
  actions.forEach((action, index) => {
    const btn = document.createElement('button');
    btn.className = action.style === 'ghost' ? 'ghost-btn' : 'primary-btn';
    btn.innerHTML = action.style === 'ghost' ? `<span>${action.label}</span>` : `<span>${action.label}</span>${iconSvg('i-arrow')}`;
    btn.addEventListener('click', () => {
      audio.click();
      closeModal();
      action.onClick?.();
    });
    wrap.appendChild(btn);
  });
  $('#modal').hidden = false;
}

function closeModal() {
  $('#modal').hidden = true;
  modalActions = [];
}

function guideModal(kind) {
  const isDig = kind === 'dig';
  openModal({
    kicker: isDig ? 'Field manual · excavation' : 'Conservation notes',
    title: isDig ? 'Read the sand.' : 'Slow hands, bright gold.',
    bodyHTML: `
      <div class="guide-steps">
        <div class="guide-step"><span class="guide-num">1</span><span><strong>${isDig ? 'Sweep with a finger' : 'Brush the grime'}</strong><span>${isDig ? 'Drag across the trench to move sand. Watch the signal meter climb.' : 'Use the dry brush to lift loose dirt from the surface.'}</span></span></div>
        <div class="guide-step"><span class="guide-num">2</span><span><strong>${isDig ? 'Clear around the signal' : 'Mist away the salt'}</strong><span>${isDig ? 'The artifact appears once enough overburden is gone. Pulse the scanner if you lose it.' : 'Switch to water. Salt crust only dissolves under a controlled mist.'}</span></span></div>
        <div class="guide-step"><span class="guide-num">3</span><span><strong>${isDig ? 'Lift the find' : 'Buff to a shine'}</strong><span>${isDig ? 'At 55% exposure the lift button wakes up. Take it back to the lab.' : 'Polish with the cloth, then send the relic to appraisal.'}</span></span></div>
      </div>`,
    actions: [{ label: isDig ? 'Back to the trench' : 'Back to the bench', style: 'primary' }]
  });
}

/* ---------------------------------------------------------
   Navigation
   --------------------------------------------------------- */
const SCREENS = ['home', 'dig', 'clean', 'appraise', 'lab', 'museum', 'shop'];

function showScreen(name) {
  const next = $(`#screen-${name}`);
  if (!next) return;
  $$('.screen').forEach(screen => screen.classList.remove('is-active'));
  next.classList.add('is-active');
  lastScreen = name;
  $$('.tab').forEach(tab => {
    const active = tab.dataset.nav === name || (name === 'dig' && tab.dataset.nav === 'home');
    tab.classList.toggle('is-active', active);
  });
  if (name === 'home') renderHome();
  if (name === 'lab') renderLab();
  if (name === 'museum') renderMuseum();
  if (name === 'shop') renderShop();
}

function goHome() {
  stopDig();
  stopClean();
  showScreen('home');
  updateWallet();
}

function stopDig() {
  if (digScene) {
    digScene.destroy();
    digScene = null;
  }
}

function stopClean() {
  if (cleanScene) {
    cleanScene.destroy();
    cleanScene = null;
  }
}

/* ---------------------------------------------------------
   Home
   --------------------------------------------------------- */
function renderHome() {
  const site = SITES[state.selectedSite];
  const locked = state.renown < site.unlock;
  const hero = $('#hero');
  hero.classList.toggle('is-locked', locked);
  $('#heroArt').innerHTML = sceneSVG(site);
  $('#heroSiteTag').textContent = siteIndexLabel(site);
  $('#heroCoord').textContent = site.coord;
  $('#heroEyebrow').textContent = `Expedition ${String(site.index).padStart(2, '0')} · ${state.collection.length} relic${state.collection.length === 1 ? '' : 's'} recovered`;
  $('#heroTitle').innerHTML = formatName(site.name);
  $('#heroSub').textContent = site.subtitle;
  $('#heroLocked').hidden = !locked;
  $('#heroLockText').textContent = `Requires ${site.unlock} renown`;
  const cta = $('#heroCtaText');
  if (state.currentRelic) {
    cta.textContent = state.currentRelic.condition != null ? 'Appraise your find' : 'Resume restoration';
  } else if (locked) {
    cta.textContent = `Reach ${site.unlock} renown`;
  } else {
    cta.textContent = 'Begin excavation';
  }

  const rail = $('#siteRail');
  rail.innerHTML = SITES.map((s, i) => {
    const isLocked = state.renown < s.unlock;
    return `<button class="site-chip ${i === state.selectedSite ? 'is-active' : ''} ${isLocked ? 'is-locked' : ''}" data-site="${i}" aria-label="${s.name}${isLocked ? ' locked' : ''}">
      <span class="site-index">0${s.index}</span>
      <span class="site-name">${s.shortName}</span>
      ${isLocked ? `<svg class="site-lock"><use href="#i-lock"></use></svg>` : ''}
    </button>`;
  }).join('');
  $$('.site-chip', rail).forEach(chip => {
    chip.addEventListener('click', () => {
      state.selectedSite = Number(chip.dataset.site);
      save();
      audio.click();
      renderHome();
    });
  });

  $('#statRecovered').textContent = state.collection.length;
  $('#statRenown').textContent = state.renown;
  $('#statRank').textContent = '· ' + rankFor(state.renown);

  const dispatch = nextObjective();
  $('#dispatchText').textContent = dispatch.text;
  $('#dispatchReward').textContent = dispatch.reward;
  updateBadges();
  updateWallet();
}

function nextObjective() {
  if (state.currentRelic?.condition != null) return { text: 'Appraise the find on your bench', reward: 'LAB' };
  if (state.currentRelic) return { text: 'Finish restoring your latest find', reward: 'LAB' };
  if (state.collection.length === 0) return { text: 'Recover your first relic', reward: '+150' };
  if (state.renown < SITES[1].unlock) return { text: `Reach ${SITES[1].unlock} renown to open the Salt Temple`, reward: 'RENOWN' };
  if (state.collection.length < 3) return { text: 'Recover three relics for the gallery', reward: '+200' };
  if (state.renown < SITES[2].unlock) return { text: `Reach ${SITES[2].unlock} renown for the Bone Valley`, reward: 'RENOWN' };
  return { text: 'Bring home a museum-grade treasure', reward: '★' };
}

function updateBadges() {
  $$('.tab-badge').forEach(el => { el.hidden = !state.currentRelic; });
}

function selectSite(delta) {
  state.selectedSite = (state.selectedSite + delta + SITES.length) % SITES.length;
  save();
  audio.click();
  renderHome();
}

function beginDig() {
  audio.ensure();
  if (state.currentRelic) {
    routeCurrentRelic();
    return;
  }
  const site = SITES[state.selectedSite];
  if (state.renown < site.unlock) {
    audio.error();
    toast(`The ${site.name} opens at ${site.unlock} renown. Sell a find to the museum.`, 3200);
    return;
  }
  startDig(site);
}

function routeCurrentRelic() {
  if (!state.currentRelic) return;
  if (state.currentRelic.condition != null) {
    showScreen('appraise');
    renderAppraisal();
  } else {
    startClean();
  }
}

/* ---------------------------------------------------------
   Dig
   --------------------------------------------------------- */
function startDig(site) {
  stopDig();
  stopClean();
  const artifactId = site.artifacts[Math.floor(Math.random() * site.artifacts.length)];
  const artifact = artifactFor(artifactId);

  $('#digSiteLabel').textContent = siteIndexLabel(site);
  $('#digSiteName').textContent = site.name;
  $('#digHint').classList.remove('is-hidden');
  $('#exposureValue').textContent = '0%';
  $('#exposureBar').style.width = '0%';
  $('#digStratum').textContent = 'Stratum I';
  $('#digDepth').textContent = '0.0 m';
  $('#digSignal').textContent = 'Signal 70%';
  $('#digNote').textContent = 'Sweep the topsoil to find the signal';
  $('#liftBtn').disabled = true;
  $('#liftBtn span').textContent = 'Lift the find';
  showScreen('dig');
  updateWallet();

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      digScene = new DigScene({
        canvas: $('#digCanvas'),
        stage: $('#digStage'),
        state,
        site,
        artifact,
        audio,
        onUpdate: ({ pct, stratum, depth, found, signal }) => {
          $('#exposureValue').textContent = `${pct}%`;
          $('#exposureBar').style.width = `${pct}%`;
          $('#digStratum').textContent = `Stratum ${stratum}`;
          $('#digDepth').textContent = `${depth} m`;
          $('#digSignal').textContent = `Signal ${signal}%`;
          $('#liftBtn').disabled = !found;
          if (found) {
            $('#digNote').textContent = 'Artifact exposed — lift it before the wind shifts';
            $('#liftBtn span').textContent = 'Lift the find';
          } else if (pct > 28) {
            $('#digNote').textContent = 'Keep sweeping — the signal is getting stronger';
          }
        },
        onFound: () => {
          toast(`${artifact.shortName} exposed · lift the find`, 2400);
          $('#digStage').classList.add('is-found');
        },
        onLift: () => {
          const sieve = levelFor(state, 'sieve');
          const chance = .12 + sieve * .1;
          let bonus = 0;
          if (Math.random() < chance) {
            bonus = 30 + sieve * 25 + Math.floor(Math.random() * 30);
            state.coins += bonus;
            audio.coin();
            updateWallet(true);
          }
          state.currentRelic = {
            artifactId,
            siteId: site.id,
            condition: null,
            dirt: 1,
            salt: 1,
            polish: 0,
            bonus,
            foundAt: Date.now()
          };
          save();
          stopDig();
          toast(bonus ? `Find lifted · bonus cache +${money(bonus)}` : 'Find lifted · off to the lab', 2600);
          startClean();
        }
      });
      const stage = $('#digStage');
      stage.addEventListener('dig-start', () => {
        $('#digHint').classList.add('is-hidden');
        state.flags.tutorialDig = true;
        save();
      }, { once: true });
    });
  });
}

function pulseScan() {
  if (!digScene) return;
  digScene.pulse();
  const scan = $('#digScan');
  scan.classList.remove('is-pinging');
  void scan.offsetWidth;
  scan.classList.add('is-pinging');
  toast('Pulse sent · dense shape beneath the sand', 1600);
}

/* ---------------------------------------------------------
   Clean
   --------------------------------------------------------- */
function startClean() {
  if (!state.currentRelic) {
    showScreen('lab');
    return;
  }
  stopClean();
  stopDig();
  const artifact = artifactFor(state.currentRelic.artifactId);
  const site = SITES.find(s => s.id === state.currentRelic.siteId) || SITES[0];

  $('#cleanRelicLabel').textContent = 'Unidentified find';
  $('#cleanFragility').textContent = artifact.fragility >= 3 ? 'Fragile' : 'Stable';
  $('#cleanGrade').textContent = 'Field condition';
  $('#cleanHint').classList.remove('is-hidden');
  $('#cleanHint').innerHTML = `<span class="hint-tool">${iconSvg('i-brush')}</span><span>Scrub away the grime</span>`;
  $('#cleanComplete').classList.remove('is-visible');
  $('#cleanNote').textContent = 'Dry-brush the grime first';
  $('#grimeLabel').textContent = 'Grime';
  $('#saltLabel').textContent = 'Salt crust';
  $('#grimeBar').style.width = '100%';
  $('#saltBar').style.width = '100%';
  $('#grimePct').textContent = '100%';
  $('#saltPct').textContent = '100%';
  $('#appraiseBtn').disabled = true;
  $('#appraiseBtn span').textContent = 'Appraise';
  selectTool('brush', false);
  showScreen('clean');
  updateWallet();

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      cleanScene = new CleanScene({
        canvas: $('#cleanCanvas'),
        stage: $('#cleanStage'),
        state,
        artifact,
        audio,
        onUpdate: ({ dirt, salt, polish, phase }) => {
          const grimePct = Math.round(dirt * 100);
          const saltPct = Math.round(salt * 100);
          $('#grimeBar').style.width = `${grimePct}%`;
          $('#grimePct').textContent = `${grimePct}%`;
          if (phase === 'clean') {
            $('#saltBar').style.width = `${saltPct}%`;
            $('#saltPct').textContent = `${saltPct}%`;
          } else {
            const lustre = Math.round(polish * 100);
            $('#saltBar').style.width = `${lustre}%`;
            $('#saltPct').textContent = `${lustre}%`;
          }
          if (phase === 'done') {
            $('#appraiseBtn').disabled = false;
            $('#cleanGrade').textContent = gradeText(state.currentRelic?.condition || 90) + ' grade';
          }
        },
        onPhase: (phase) => {
          if (phase === 'polish') {
            $('#saltLabel').textContent = 'Lustre';
            $('#cleanRelicLabel').textContent = artifact.name;
            $('#cleanHint').classList.remove('is-hidden');
            $('#cleanHint').innerHTML = `<span class="hint-tool">${iconSvg('i-cloth')}</span><span>Buff the surface with the cloth</span>`;
            $('#cleanNote').textContent = 'Buff to a museum shine';
            selectTool('cloth', true);
            toast('Encrustation cleared · buff to a museum shine', 2600);
            setTimeout(() => $('#cleanHint').classList.add('is-hidden'), 3600);
          }
          if (phase === 'done') {
            $('#cleanHint').classList.add('is-hidden');
            $('#cleanComplete').classList.add('is-visible');
            $('#appraiseBtn').disabled = false;
            $('#appraiseBtn span').textContent = 'Appraise find';
            $('#cleanGrade').textContent = gradeText(state.currentRelic?.condition || 90) + ' grade';
            $('#cleanRelicLabel').textContent = artifact.name;
          }
        },
        onComplete: ({ condition, dirt, salt, polish }) => {
          if (!state.currentRelic) return;
          state.currentRelic.condition = condition;
          state.currentRelic.dirt = dirt;
          state.currentRelic.salt = salt;
          state.currentRelic.polish = polish;
          state.currentRelic.cat = state.currentRelic.cat || String(100 + state.collection.length + 1);
          save();
          $('#cleanGrade').textContent = gradeText(condition) + ' grade';
          updateBadges();
        },
        onHint: (message) => {
          $('#cleanNote').textContent = message;
        }
      });
      const stage = $('#cleanStage');
      stage.addEventListener('clean-start', () => {
        $('#cleanHint').classList.add('is-hidden');
        state.flags.tutorialClean = true;
        save();
      }, { once: true });
    });
  });
}

function selectTool(tool, notify = true) {
  $$('.tool-btn').forEach(btn => btn.classList.toggle('is-active', btn.dataset.tool === tool));
  if (cleanScene) cleanScene.setTool(tool);
  if (notify) {
    const labels = { brush: 'Dry brush selected', water: 'Mister selected', cloth: 'Conservator’s cloth selected' };
    toast(labels[tool], 1000);
  }
}

function goAppraise() {
  if (!state.currentRelic || state.currentRelic.condition == null) return;
  stopClean();
  showScreen('appraise');
  renderAppraisal();
}

/* ---------------------------------------------------------
   Appraisal
   --------------------------------------------------------- */
function appraisalOffers() {
  const relic = state.currentRelic;
  if (!relic) return null;
  const artifact = artifactFor(relic.artifactId);
  const condition = relic.condition ?? 85;
  const market = Math.round(artifact.value * (.62 + (condition / 100) * .72));
  const collector = Math.round(market * (1.1 + Math.random() * .13));
  const museum = Math.round(market * .89);
  const renown = Math.round(artifact.rarity * 2.4 + condition / 15) + (state.flags.firstSale ? 0 : 3);
  return { artifact, condition, market, collector, museum, renown };
}

function renderAppraisal() {
  const relic = state.currentRelic;
  if (!relic) return;
  const offers = appraisalOffers();
  if (!offers) return;
  if (!relic.offers) {
    relic.offers = { collector: offers.collector, museum: offers.museum, renown: offers.renown, market: offers.market };
    save();
  }
  const o = relic.offers;
  const a = offers.artifact;
  $('#appraiseImg').src = artifactImage(a.id, 360);
  $('#appraiseName').textContent = a.name;
  $('#appraiseEra').textContent = a.era;
  $('#appraiseDesc').textContent = a.desc;
  $('#appraiseCondition').textContent = `${offers.condition}%`;
  $('#appraiseMarket').textContent = money(o.market);
  $('#appraiseGrade').textContent = gradeText(offers.condition);
  $('#appraiseStamp').textContent = offers.condition >= 95 ? 'Museum grade' : offers.condition >= 84 ? 'Conserved' : 'Stable';
  $('#appraiseId').textContent = `CAT. 0${relic.cat || 101}`;
  $('#appraiseRarity').innerHTML = Array.from({ length: 5 }, (_, i) =>
    `<svg class="star ${i < a.rarity ? '' : 'empty'}"><use href="#i-star"></use></svg>`
  ).join('') + `<span class="rarity-text">${['', 'Common', 'Notable', 'Rare', 'Museum', 'Masterwork'][a.rarity]}</span>`;
  $('#museumValue').textContent = money(o.museum);
  $('#collectorValue').textContent = money(o.collector);
  $('#museumRenown').textContent = `+${o.renown}`;
  $('#soldOverlay').hidden = true;
}

function sellRelic(buyer) {
  const relic = state.currentRelic;
  if (!relic || !relic.offers) return;
  const artifact = artifactFor(relic.artifactId);
  const offers = relic.offers;
  const amount = buyer === 'museum' ? offers.museum : offers.collector;
  let grant = 0;
  if (!state.flags.firstRelic) {
    grant = 150;
    state.flags.firstRelic = true;
  }
  state.coins += amount + grant;
  state.totalEarned += amount;
  if (buyer === 'museum') state.renown += offers.renown;
  state.flags.firstSale = true;
  state.collection.push({
    artifactId: relic.artifactId,
    name: artifact.name,
    condition: relic.condition ?? 85,
    value: amount,
    buyer: buyer === 'museum' ? 'Atlas Museum' : 'Private collector',
    renown: buyer === 'museum' ? offers.renown : 0,
    date: Date.now()
  });
  state.currentRelic = null;
  save();
  updateWallet(true);
  updateBadges();

  const isMuseum = buyer === 'museum';
  $('#soldEyebrow').textContent = isMuseum ? 'Acquired by the Atlas Museum' : 'Sold to a private collector';
  $('#soldTitle').innerHTML = isMuseum ? 'A new treasure<br>enters the archive.' : 'The deal is<br>done, quietly.';
  $('#soldAmount').textContent = money(amount + grant);
  $('#soldRenown').textContent = isMuseum ? `+${offers.renown}` : '—';
  $('#soldFlavor').textContent = grant
    ? `The Society adds a first-find grant of ${money(grant)}. ${isMuseum ? 'Curator Hana places it in the sunrise gallery.' : 'The buyer asks that you do not mention the tomb.'}`
    : (isMuseum ? 'Curator Hana places it in the sunrise gallery.' : 'The buyer asks that you do not mention the tomb.');
  $('#soldOverlay').hidden = false;
  audio.coin();
  vibrate([20, 40, 30]);
}

