  state.totalEarned += amount;
  if (buyer === 'museum') state.renown += offers.renown;

import { drawArtifact, drawArtifactShadow } from './art.js';
import { levelFor } from './data.js';

const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const lerp = (a, b, t) => a + (b - a) * t;

function seeded(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export class DigScene {
  constructor({ canvas, stage, state, site, artifact, audio, onUpdate, onFound, onLift }) {
    this.canvas = canvas;
    this.stage = stage;
    this.ctx = canvas.getContext('2d');
    this.state = state;
    this.site = site;
    this.artifact = artifact;
    this.audio = audio;
    this.onUpdate = onUpdate || (() => {});
    this.onFound = onFound || (() => {});
    this.onLift = onLift || (() => {});

    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.w = 0;
    this.h = 0;
    this.drawing = false;
    this.last = null;
    this.progress = 0;
    this.found = false;
    this.lifted = false;
    this.particles = [];
    this.pointer = null;
    this.lastHaptic = 0;
    this.outlinePulse = 0;
    this.raf = 0;
    this.started = false;

    this.onDown = this.onDown.bind(this);
    this.onMove = this.onMove.bind(this);
    this.onUp = this.onUp.bind(this);
    this.loop = this.loop.bind(this);

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(stage);
    this.bind();
    this.resize();
    this.raf = requestAnimationFrame(this.loop);
  }

  bind() {
    this.canvas.addEventListener('pointerdown', this.onDown, { passive: false });
    this.canvas.addEventListener('pointermove', this.onMove, { passive: false });
    this.canvas.addEventListener('pointerup', this.onUp);
    this.canvas.addEventListener('pointercancel', this.onUp);
    this.canvas.addEventListener('pointerleave', (e) => {
      if (!this.drawing) this.pointer = null;
    });
  }

  destroy() {
    this.resizeObserver.disconnect();
    cancelAnimationFrame(this.raf);
    this.canvas.removeEventListener('pointerdown', this.onDown);
    this.canvas.removeEventListener('pointermove', this.onMove);
    this.canvas.removeEventListener('pointerup', this.onUp);
    this.canvas.removeEventListener('pointercancel', this.onUp);
    this.stage.classList.remove('is-lifting');
  }

  resize() {
    const rect = this.stage.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const w = Math.round(rect.width);
    const h = Math.round(rect.height);
    if (w === this.w && h === this.h) return;
    this.w = w;
    this.h = h;
    this.canvas.width = Math.round(w * this.dpr);
    this.canvas.height = Math.round(h * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.build();
    this.started = true;
    this.emit();
  }

  makeCanvas() {
    const c = document.createElement('canvas');
    c.width = Math.round(this.w * this.dpr);
    c.height = Math.round(this.h * this.dpr);
    const ctx = c.getContext('2d');
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    return { c, ctx };
  }

  build() {
    const { w, h } = this;
    this.base = this.makeCanvas();
    this.sand = this.makeCanvas();
    this.relicCanvas = this.makeCanvas();

    this.cx = w * .5;
    this.cy = h * .535;
    this.relicSize = Math.min(w, h) * .58;

    this.paintRelic();
    this.paintBase();
    this.paintSand();
    this.buildGrid();

    this.progress = 0;
    this.found = false;
    this.lifted = false;
    this.particles.length = 0;
    this.last = null;
    this.drawing = false;
  }

  paintBase() {
    const { ctx } = this.base;
    const { w, h } = this;
    const g = ctx.createLinearGradient(0, 0, w * .3, h);
    g.addColorStop(0, '#5d4028');
    g.addColorStop(.45, '#715032');
    g.addColorStop(1, '#4d3421');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // compacted stratigraphy
    const layers = [
      { y: h * .18, color: 'rgba(51,33,20,.25)', height: h * .1 },
      { y: h * .43, color: 'rgba(113,78,43,.25)', height: h * .16 },
      { y: h * .72, color: 'rgba(45,29,18,.32)', height: h * .15 }
    ];
    for (const layer of layers) {
      ctx.fillStyle = layer.color;
      ctx.beginPath();
      ctx.moveTo(0, layer.y);
      for (let x = 0; x <= w; x += 30) {
        ctx.lineTo(x, layer.y + Math.sin(x * .04 + layer.y) * 4);
      }
      ctx.lineTo(w, layer.y + layer.height);
      for (let x = w; x >= 0; x -= 24) {
        ctx.lineTo(x, layer.y + layer.height + Math.cos(x * .035) * 5);
      }
      ctx.closePath();
      ctx.fill();
    }

    // lower sand texture
    const r = seeded(73);
    for (let i = 0; i < 460; i++) {
      const x = r() * w;
      const y = r() * h;
      const rad = .4 + r() * 1.5;
      ctx.beginPath();
      ctx.arc(x, y, rad, 0, Math.PI * 2);
      ctx.fillStyle = r() > .5 ? `rgba(226,183,119,${.05 + r() * .12})` : `rgba(35,22,13,${.06 + r() * .12})`;
      ctx.fill();
    }

    // scattered stones and bone chips
    for (let i = 0; i < 16; i++) {
      const x = r() * w, y = r() * h;
      const rw = 2 + r() * 7, rh = 1.5 + r() * 4;
      ctx.beginPath();
      ctx.ellipse(x, y, rw, rh, r() * 3, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${60 + r() * 30},${45 + r() * 20},${31 + r() * 15},.65)`;
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(x - rw * .18, y - rh * .25, rw * .45, rh * .35, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(226,193,140,.14)';
      ctx.fill();
    }

    // secondary ceramic shard
    ctx.save();
    ctx.translate(w * .18, h * .7);
    ctx.rotate(-.4);
    ctx.beginPath();
    ctx.moveTo(-10, 0); ctx.lineTo(2, -8); ctx.lineTo(13, -2); ctx.lineTo(7, 7); ctx.lineTo(-6, 6);
    ctx.closePath();
    ctx.fillStyle = '#9a6a3f';
    ctx.fill();
    ctx.strokeStyle = 'rgba(45,28,14,.55)';
    ctx.stroke();
    ctx.restore();

    // dark rim
    const edge = ctx.createLinearGradient(0, 0, 0, h);
    edge.addColorStop(0, 'rgba(20,12,6,.65)');
    edge.addColorStop(.08, 'rgba(20,12,6,0)');
    edge.addColorStop(.9, 'rgba(20,12,6,0)');
    edge.addColorStop(1, 'rgba(20,12,6,.62)');
    ctx.fillStyle = edge;
    ctx.fillRect(0, 0, w, h);
    const side = ctx.createLinearGradient(0, 0, w, 0);
    side.addColorStop(0, 'rgba(20,12,6,.45)');
    side.addColorStop(.1, 'rgba(20,12,6,0)');
    side.addColorStop(.9, 'rgba(20,12,6,0)');
    side.addColorStop(1, 'rgba(20,12,6,.45)');
    ctx.fillStyle = side;
    ctx.fillRect(0, 0, w, h);

    // artifact shadow drawn before relic
    drawArtifactShadow(ctx, this.cx, this.cy, this.relicSize, .42);
    ctx.drawImage(this.relicCanvas.c, 0, 0, w, h);
  }

  paintRelic() {
    const { ctx } = this.relicCanvas;
    const { w, h } = this;
    ctx.clearRect(0, 0, w, h);
    drawArtifact(ctx, this.artifact.art, this.cx, this.cy, this.relicSize);

    // encrusted overlay, clipped to artifact silhouette
    ctx.save();
    ctx.globalCompositeOperation = 'source-atop';
    ctx.fillStyle = 'rgba(69, 48, 29, .58)';
    ctx.fillRect(this.cx - this.relicSize, this.cy - this.relicSize, this.relicSize * 2, this.relicSize * 2);
    const r = seeded(917);
    for (let i = 0; i < 90; i++) {
      const a = r() * Math.PI * 2;
      const rad = r() * this.relicSize * .42;
      const x = this.cx + Math.cos(a) * rad;
      const y = this.cy + Math.sin(a) * rad * .9;
      const size = 1 + r() * 7;
      ctx.beginPath();
      ctx.arc(x, y, size, 0, Math.PI * 2);
      ctx.fillStyle = r() > .7
        ? `rgba(215, 200, 170, ${.1 + r() * .22})`
        : `rgba(48, 31, 17, ${.1 + r() * .28})`;
      ctx.fill();
    }
    // salt bloom
    for (let i = 0; i < 22; i++) {
      const a = r() * Math.PI * 2;
      const rad = r() * this.relicSize * .4;
      const x = this.cx + Math.cos(a) * rad;
      const y = this.cy + Math.sin(a) * rad;
      const size = 2 + r() * 9;
      ctx.beginPath();
      ctx.arc(x, y, size, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(233, 228, 209, ${.05 + r() * .14})`;
      ctx.fill();
    }
    ctx.restore();

    // fine specular
    ctx.save();
    ctx.globalCompositeOperation = 'source-atop';
    ctx.beginPath();
    ctx.ellipse(this.cx - this.relicSize * .2, this.cy - this.relicSize * .22, this.relicSize * .24, this.relicSize * .08, -.6, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 239, 196, .08)';
    ctx.fill();
    ctx.restore();
  }

  paintSand() {
    const { ctx } = this.sand;
    const { w, h } = this;
    const r = seeded(2024);

    const g = ctx.createLinearGradient(0, 0, w * .3, h);
    g.addColorStop(0, '#e0bb7d');
    g.addColorStop(.38, '#d3a666');
    g.addColorStop(.72, '#c39152');
    g.addColorStop(1, '#b37e43');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // wind ripples
    ctx.lineWidth = 1;
    for (let i = 0; i < 22; i++) {
      const y = (i / 22) * h + Math.sin(i) * 7;
      ctx.beginPath();
      for (let x = -20; x <= w + 20; x += 12) {
        const yy = y + Math.sin(x * .045 + i * .8) * 3.2 + Math.cos(x * .02) * 2;
        x === -20 ? ctx.moveTo(x, yy) : ctx.lineTo(x, yy);
      }
      ctx.strokeStyle = i % 3 === 0 ? 'rgba(255, 233, 190, .16)' : 'rgba(110, 73, 35, .075)';
      ctx.stroke();
    }

    // wind-blown patches
    for (let i = 0; i < 15; i++) {
      const x = r() * w, y = r() * h;
      const rw = 20 + r() * 80, rh = 8 + r() * 30;
      const pg = ctx.createRadialGradient(x, y, 0, x, y, rw);
      pg.addColorStop(0, r() > .5 ? 'rgba(244, 214, 158, .14)' : 'rgba(126, 84, 40, .09)');
      pg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(1, rh / rw);
      ctx.fillStyle = pg;
      ctx.beginPath();
      ctx.arc(0, 0, rw, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // central mound
    const mound = ctx.createRadialGradient(this.cx, this.cy, 2, this.cx, this.cy, this.relicSize * .75);
    mound.addColorStop(0, 'rgba(250, 222, 170, .26)');
    mound.addColorStop(.58, 'rgba(230, 192, 131, .11)');
    mound.addColorStop(1, 'rgba(90, 57, 27, 0)');
    ctx.fillStyle = mound;
    ctx.beginPath();
    ctx.arc(this.cx, this.cy, this.relicSize * .76, 0, Math.PI * 2);
    ctx.fill();

    // grit
    for (let i = 0; i < 820; i++) {
      const x = r() * w, y = r() * h;
      const rad = .3 + r() * 1.5;
      ctx.beginPath();
      ctx.arc(x, y, rad, 0, Math.PI * 2);
      ctx.fillStyle = r() > .48 ? `rgba(255, 236, 195, ${.08 + r() * .2})` : `rgba(84, 54, 25, ${.06 + r() * .18})`;
      ctx.fill();
    }

    // pebbles / hardpan
    for (let i = 0; i < 20; i++) {
      const x = r() * w, y = r() * h;
      const rw = 1.5 + r() * 4.2, rh = 1 + r() * 2.8;
      ctx.beginPath();
      ctx.ellipse(x, y, rw, rh, r() * 3, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${85 + r() * 45},${62 + r() * 30},${38 + r() * 20},.55)`;
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(x - rw * .2, y - rh * .25, rw * .45, rh * .32, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255, 236, 199, .17)';
      ctx.fill();
    }

    // dry twigs
    ctx.strokeStyle = 'rgba(92, 58, 27, .32)';
    ctx.lineWidth = 1.2;
    for (let i = 0; i < 5; i++) {
      const x = r() * w, y = r() * h;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + 10 + r() * 12, y - 3 + r() * 7);
      ctx.lineTo(x + 18 + r() * 8, y + 2 + r() * 4);
      ctx.stroke();
    }

    // edge shade
    const edge = ctx.createLinearGradient(0, 0, 0, h);
    edge.addColorStop(0, 'rgba(75, 46, 21, .38)');
    edge.addColorStop(.08, 'rgba(75, 46, 21, 0)');
    edge.addColorStop(.9, 'rgba(75, 46, 21, 0)');
    edge.addColorStop(1, 'rgba(75, 46, 21, .4)');
    ctx.fillStyle = edge;
    ctx.fillRect(0, 0, w, h);
    const side = ctx.createLinearGradient(0, 0, w, 0);

import { drawArtifact, drawArtifactShadow } from './art.js';
import { levelFor, cleaningGrade } from './data.js';

const clamp = (n, a, b) => Math.max(a, Math.min(b, n));

function seeded(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export class CleanScene {
  constructor({ canvas, stage, state, artifact, audio, onUpdate, onPhase, onComplete, onHint }) {
    this.canvas = canvas;
    this.stage = stage;
    this.ctx = canvas.getContext('2d');
    this.state = state;
    this.artifact = artifact;
    this.audio = audio;
    this.onUpdate = onUpdate || (() => {});
    this.onPhase = onPhase || (() => {});
    this.onComplete = onComplete || (() => {});
    this.onHint = onHint || (() => {});

    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.w = 0;
    this.h = 0;
    this.tool = 'brush';
    this.phase = 'clean';
    this.drawing = false;
    this.pointer = null;
    this.last = null;
    this.particles = [];
    this.raf = 0;
    this.started = false;
    this.completed = false;
    this.polish = 0;
    this.dirtCount = 0;
    this.saltCount = 0;
    this.dirtTotal = 1;
    this.saltTotal = 1;
    this.lastHaptic = 0;
    this.lastSound = 0;
    this.lastHint = 0;

    this.onDown = this.onDown.bind(this);
    this.onMove = this.onMove.bind(this);
    this.onUp = this.onUp.bind(this);
    this.loop = this.loop.bind(this);

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(stage);
    this.bind();
    this.resize();
    this.raf = requestAnimationFrame(this.loop);
  }

  bind() {
    this.canvas.addEventListener('pointerdown', this.onDown, { passive: false });
    this.canvas.addEventListener('pointermove', this.onMove, { passive: false });
    this.canvas.addEventListener('pointerup', this.onUp);
    this.canvas.addEventListener('pointercancel', this.onUp);
    this.canvas.addEventListener('pointerleave', () => {
      if (!this.drawing) this.pointer = null;
    });
  }

  destroy() {
    this.resizeObserver.disconnect();
    cancelAnimationFrame(this.raf);
    this.canvas.removeEventListener('pointerdown', this.onDown);
    this.canvas.removeEventListener('pointermove', this.onMove);
    this.canvas.removeEventListener('pointerup', this.onUp);
    this.canvas.removeEventListener('pointercancel', this.onUp);
  }

  resize() {
    const rect = this.stage.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const w = Math.round(rect.width);
    const h = Math.round(rect.height);
    if (w === this.w && h === this.h) return;
    this.w = w;
    this.h = h;
    this.canvas.width = Math.round(w * this.dpr);
    this.canvas.height = Math.round(h * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.build();
    this.started = true;
    this.emit();
  }

  makeCanvas() {
    const c = document.createElement('canvas');
    c.width = Math.round(this.w * this.dpr);
    c.height = Math.round(this.h * this.dpr);
    const ctx = c.getContext('2d');
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    return { c, ctx };
  }

  build() {
    const { w, h } = this;
    this.bg = this.makeCanvas();
    this.base = this.makeCanvas();
    this.dirt = this.makeCanvas();
    this.salt = this.makeCanvas();
    this.mask = this.makeCanvas();

    this.cx = w * .5;
    this.cy = h * .52;
    this.size = Math.min(w, h) * .64;

    this.paintBackground();
    drawArtifact(this.base.ctx, this.artifact.art, this.cx, this.cy, this.size);

    this.mask.ctx.clearRect(0, 0, w, h);
    drawArtifact(this.mask.ctx, this.artifact.art, this.cx, this.cy, this.size);

    this.paintDirt();
    this.paintSalt();
    this.buildGrid();

    this.particles.length = 0;
    this.pointer = null;
    this.last = null;
    this.drawing = false;
    this.completed = false;
    this.polish = 0;
    this.phase = 'clean';
    this.dirtCount = this.dirtTotal;
    this.saltCount = this.saltTotal;
  }

  paintBackground() {
    const { ctx } = this.bg;
    const { w, h } = this;
    const g = ctx.createRadialGradient(w * .5, h * .42, 10, w * .5, h * .48, Math.max(w, h) * .72);
    g.addColorStop(0, '#32413b');
    g.addColorStop(.48, '#1b2723');
    g.addColorStop(1, '#0c1311');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // faint conservation grid
    ctx.strokeStyle = 'rgba(186, 220, 204, .045)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x += 28) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
    }
    for (let y = 0; y <= h; y += 28) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }

    // tray rim
    const inset = Math.min(w, h) * .08;
    const r = 16;
    ctx.beginPath();
    ctx.roundRect(inset, inset, w - inset * 2, h - inset * 2, r);
    ctx.fillStyle = 'rgba(255,255,255,.018)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(198, 226, 211, .12)';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.beginPath();
    ctx.roundRect(inset + 4, inset + 4, w - inset * 2 - 8, h - inset * 2 - 8, r - 4);
    ctx.strokeStyle = 'rgba(198, 226, 211, .045)';
    ctx.stroke();

    // ruler ticks
    ctx.strokeStyle = 'rgba(198, 226, 211, .12)';
    for (let i = 0; i < 17; i++) {
      const x = inset + 12 + i * ((w - inset * 2 - 24) / 16);
      const len = i % 4 === 0 ? 7 : 3;
      ctx.beginPath();
      ctx.moveTo(x, h - inset - 9);
      ctx.lineTo(x, h - inset - 9 - len);
      ctx.stroke();
    }

    // ambient dust
    const rr = seeded(91);
    for (let i = 0; i < 55; i++) {
      ctx.beginPath();
      ctx.arc(rr() * w, rr() * h, .3 + rr() * 1.1, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(220, 236, 224, ${.03 + rr() * .08})`;
      ctx.fill();
    }

    drawArtifactShadow(ctx, this.cx, this.cy, this.size, .5);

    // glass reflection
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const sheen = ctx.createLinearGradient(0, inset, w, h * .7);
    sheen.addColorStop(0, 'rgba(255,255,255,.025)');
    sheen.addColorStop(.35, 'rgba(255,255,255,0)');
    sheen.addColorStop(.62, 'rgba(255,255,255,.018)');
    sheen.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = sheen;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  }

  paintDirt() {
    const { ctx } = this.dirt;
    const { w, h } = this;
    ctx.clearRect(0, 0, w, h);
    const rr = seeded(113);

    ctx.fillStyle = 'rgba(72, 54, 35, .92)';
    ctx.fillRect(0, 0, w, h);

    // mottled encrustation
    for (let i = 0; i < 130; i++) {
      const x = rr() * w, y = rr() * h;
      const rw = 3 + rr() * 20, rh = 2 + rr() * 13;
      const g = ctx.createRadialGradient(x, y, 0, x, y, rw);
      const dark = rr() > .46;
      g.addColorStop(0, dark ? `rgba(45, 32, 20, ${.16 + rr() * .28})` : `rgba(137, 108, 72, ${.1 + rr() * .23})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(1, rh / rw);
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(0, 0, rw, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // grime grain
    for (let i = 0; i < 460; i++) {
      ctx.beginPath();
      ctx.arc(rr() * w, rr() * h, .3 + rr() * 1.6, 0, Math.PI * 2);
      ctx.fillStyle = rr() > .5 ? `rgba(154, 123, 79, ${.05 + rr() * .17})` : `rgba(38, 27, 17, ${.06 + rr() * .18})`;
      ctx.fill();
    }

    // crust cracks
    ctx.strokeStyle = 'rgba(35, 24, 15, .32)';
    for (let i = 0; i < 12; i++) {
      let x = rr() * w, y = rr() * h;
      ctx.beginPath();
      ctx.moveTo(x, y);
      for (let j = 0; j < 4; j++) {
        x += (rr() - .5) * 28;
        y += (rr() - .5) * 28;
        ctx.lineTo(x, y);
      }
      ctx.lineWidth = .6 + rr() * .8;
      ctx.stroke();
    }

    // clip to artifact silhouette
    ctx.save();
    ctx.globalCompositeOperation = 'destination-in';
    ctx.drawImage(this.mask.c, 0, 0, w, h);
    ctx.restore();
  }

  paintSalt() {
    const { ctx } = this.salt;
    const { w, h } = this;
    ctx.clearRect(0, 0, w, h);
    const rr = seeded(451);

    // base crust
    ctx.fillStyle = 'rgba(224, 220, 199, .42)';
    ctx.fillRect(0, 0, w, h);

    // crystalline blooms
    for (let i = 0; i < 80; i++) {
      const x = rr() * w, y = rr() * h;
      const r = 4 + rr() * 18;
      const g = ctx.createRadialGradient(x - r * .2, y - r * .25, 0, x, y, r);
      g.addColorStop(0, `rgba(255, 253, 239, ${.18 + rr() * .22})`);
      g.addColorStop(.55, `rgba(211, 219, 207, ${.08 + rr() * .14})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }

    // salt veins / crack fill
    for (let i = 0; i < 22; i++) {
      let x = rr() * w, y = rr() * h;
      ctx.beginPath();
      ctx.moveTo(x, y);
      for (let j = 0; j < 4; j++) {
        x += (rr() - .5) * 18;
        y += (rr() - .5) * 18;
        ctx.lineTo(x, y);
      }
      ctx.strokeStyle = `rgba(248, 247, 231, ${.08 + rr() * .22})`;
      ctx.lineWidth = 1 + rr() * 2.6;
      ctx.stroke();
    }

    // blue-grey shadows in the salt
    for (let i = 0; i < 30; i++) {
      ctx.beginPath();
      ctx.arc(rr() * w, rr() * h, 2 + rr() * 9, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(117, 139, 133, ${.025 + rr() * .09})`;
      ctx.fill();
    }

    // clip
    ctx.save();
    ctx.globalCompositeOperation = 'destination-in';
    ctx.drawImage(this.mask.c, 0, 0, w, h);
    ctx.restore();
  }

  buildGrid() {
    const { w, h } = this;
    const mw = this.mask.c.width;
    const mh = this.mask.c.height;
    const data = this.mask.ctx.getImageData(0, 0, mw, mh).data;
    this.cell = Math.max(4, Math.round(Math.min(w, h) / 58));
    this.cols = Math.ceil(w / this.cell);
    this.rows = Math.ceil(h / this.cell);
    this.gridMask = new Uint8Array(this.cols * this.rows);
    this.dirtGrid = new Uint8Array(this.cols * this.rows);
    this.saltGrid = new Uint8Array(this.cols * this.rows);
    this.dirtTotal = 0;
    this.saltTotal = 0;
    for (let gy = 0; gy < this.rows; gy++) {
      for (let gx = 0; gx < this.cols; gx++) {
        const x = Math.round((gx + .5) * this.cell * this.dpr);
        const y = Math.round((gy + .5) * this.cell * this.dpr);
        if (x < 0 || y < 0 || x >= mw || y >= mh) continue;
        if (data[(y * mw + x) * 4 + 3] > 32) {
          const idx = gy * this.cols + gx;
          this.gridMask[idx] = 1;
          this.dirtGrid[idx] = 1;
          this.saltGrid[idx] = 1;
          this.dirtTotal++;
          this.saltTotal++;
        }
      }
    }
    this.dirtCount = this.dirtTotal;
    this.saltCount = this.saltTotal;
  }

  setTool(tool) {
    if (tool === this.tool) return;
    this.tool = tool;
    this.pointer = null;
    this.audio.click();
  }

  point(e) {
    const rect = this.canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  }

  onDown(e) {
    if (this.completed) return;
    e.preventDefault();
    this.audio.ensure();
    this.drawing = true;
    this.canvas.setPointerCapture?.(e.pointerId);
    const p = this.point(e);
    this.last = p;
    this.pointer = p;
    this.applyTool(p.x, p.y);
    this.stage.dispatchEvent(new CustomEvent('clean-start'));
  }

  onMove(e) {
    if (this.completed) return;
    const p = this.point(e);
    this.pointer = p;
    if (!this.drawing) return;
    e.preventDefault();
    if (this.last) {
      const dx = p.x - this.last.x, dy = p.y - this.last.y;
      const dist = Math.hypot(dx, dy);
      const steps = Math.max(1, Math.ceil(dist / 6));
      for (let i = 1; i <= steps; i++) {
        this.applyTool(this.last.x + dx * (i / steps), this.last.y + dy * (i / steps));
      }
    } else {
      this.applyTool(p.x, p.y);
    }
    this.last = p;
  }

  onUp() {
    this.drawing = false;
    this.last = null;
    this.emit();
  }

  toolRadius() {
    const scale = Math.min(1.2, Math.max(.8, Math.min(this.w, this.h) / 360));
    if (this.tool === 'brush') return (46 + (levelFor(this.state, 'brush') - 1) * 6) * scale;
    if (this.tool === 'water') return (58 + (levelFor(this.state, 'water') - 1) * 8) * scale;
    return (44 + (levelFor(this.state, 'cloth') - 1) * 6) * scale;
  }

  applyTool(x, y) {
    if (this.phase === 'done') return;
    const radius = this.toolRadius();
    if (this.tool === 'brush') {
      if (this.phase === 'polish') {
        this.hint('The crust is gone — buff it with the cloth.', 900);
        return;
      }
      const before = this.dirtCount;
      this.erase(this.dirt.ctx, x, y, radius);
      this.mark('dirt', x, y, radius * .88);
      if (this.dirtCount < before) {
        this.audio.brush();
        this.spawnDust(x, y, radius, 'rgba(105, 82, 54,');

  if (buyer === 'museum') state.renown += offers.renown;
  state.flags.firstSale = true;
  state.collection.push({
    artifactId: relic.artifactId,
    name: artifact.name,
    condition: relic.condition ?? 85,
    value: amount,
    buyer: buyer === 'museum' ? 'Atlas Museum' : 'Private collector',
    renown: buyer === 'museum' ? offers.renown : 0,
