playwright-cli -s=dune run-code "async (page) => {
  const rect = await page.evaluate(() => { const d=window.__DUNE.digScene; const r=document.querySelector('#digStage').getBoundingClientRect(); return {x:r.x,y:r.y,w:r.width,h:r.height,cx:d.cx,cy:d.cy,size:d.relicSize}; });
  const cx = rect.x + rect.cx, cy = rect.y + rect.cy;
  const rx = rect.size * 0.46, ry = rect.size * 0.46;
  await page.mouse.move(cx-rx, cy-ry);
  await page.mouse.down();
  const rows = 12;
  for (let i=0;i<=rows;i++) {
    const y = cy - ry + (2*ry)*(i/rows);
    const left = cx - rx + (i%2?2:0);
    const right = cx + rx - (i%2?2:0);
    if (i%2===0) { await page.mouse.move(left,y,{steps:10}); await page.mouse.move(right,y,{steps:24}); }
    else { await page.mouse.move(right,y,{steps:10}); await page.mouse.move(left,y,{steps:24}); }
  }
  await page.mouse.up();
